from pathlib import Path
import json,html,textwrap
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import letter
from reportlab.lib.colors import HexColor
R=Path(__file__).resolve().parents[3]
t=(R/'tools/business-startup-checklist/index.html').read_text()
configs=[('daily-schedule-builder','Free Daily Schedule Builder: Time Blocks & Overlap Check','Build a same-day schedule, spot overlapping tasks, review free gaps and export CSV or a JSON backup. Includes a blank printable daily schedule PDF.', '''<h2>Build a realistic daily schedule</h2><p>Choose a fixed date and same-day start and end. Add 1–30 named entries with start and end times inside that window. Overnight entries are not supported. Include breaks, travel and preparation when they occupy time. The tool identifies overlaps; you decide whether and how to move the work.</p><h3>How time is counted</h3><p>Task minutes add every entry duration. Occupied minutes measure the union of all intervals, so simultaneous tasks do not count twice. Free minutes equal day-window minutes minus occupied minutes. Overlapping task minutes equal summed task durations minus occupied time. With three simultaneous tasks, overlapping task minutes can exceed the length of the conflict interval. This is duplicate time promised, not a count of conflict pairs. Tasks that touch at an endpoint do not overlap.</p><h3>Fictional example and a conflict</h3><p>A 09:00–17:00 day has 480 minutes. Focus work 09:00–10:00, a call 10:00–10:30 and delivery work 11:00–12:00 occupy 150 minutes, leaving 330 free. Adding a 09:30–10:15 task raises task minutes to 195 while occupied time stays 150; 45 minutes are promised twice. Remove the conflict or reduce commitments before treating the schedule as usable.</p><h3>Save and print your day</h3><p>Review after every change. CSV contains your reviewed named entries; JSON restores editable entries in this exact tool. Print / Save PDF prints the reviewed report using your device dialog. The separate one-page US Letter PDF is a static blank writing sheet, not fillable. Entries are kept on this page only, with no automatic saving or synchronization.</p><p>Use the <a href="/journal/daily-planner-2026-free-layouts/">daily layout guide</a> to choose priorities and buffers, or the <a href="/journal/student-planner-guide/">student planner guide</a> to work backward from deadlines. This schedule does not provide reminders, calendar integration or task-duration predictions.</p>'''),('business-idea-comparison','Free Business Idea Comparison: Weighted Score Worksheet','Compare two to five business ideas using your own evidence ratings and weights. Review ties, export CSV, keep JSON backups and print a blank PDF worksheet.', '''<h2>Compare ideas before writing a full plan</h2><p>Compare 2–5 ideas using four criteria: customer evidence, delivery fit, cash fit and testability. Higher ratings always mean a stronger fit. For each idea, enter four whole-number ratings from 0 to 5 and a note explaining the evidence or uncertainty. Cash fit is your judgment about available resources relative to the test, not a money amount or financial projection.</p><h3>Set weights and understand the formula</h3><p>Choose integer weights from 0 to 10. At least one must be positive. A zero weight excludes a criterion. Weighted score = sum of rating × weight ÷ (5 × sum of weights) × 100. Ranking uses unrounded weighted points; equal points share rank. The two-decimal display can hide tiny differences, so inspect your inputs when displayed scores look equal.</p><h3>Fictional example</h3><p>With weights 4, 3, 2 and 1, a design service rated 4, 3, 2 and 4 earns 33 ÷ 50 × 100 = 66. A repair service rated 3, 4, 4 and 3 earns 35 ÷ 50 × 100 = 70. These invented scores are an illustration, not market research. Changing customer-evidence weight from 4 to 10 gives the design idea 57 ÷ 80 = 71.25 and repair 53 ÷ 80 = 66.25: the order reverses. Record why a weight change is justified.</p><h3>Use a score to choose a test</h3><p>A higher score does not prove demand, profit, funding eligibility or business viability. Treat missing evidence as a task to investigate. Choose a small test, its owner, cost ceiling, date and decision rule. Retain the original comparison rather than changing ratings to justify a preferred idea. Keep money and customer-sensitive records out of shareable notes.</p><h3>Keep a copy</h3><p>CSV includes ratings, evidence notes, weights and reviewed scores. A same-tool JSON backup restores editable inputs after confirmation; no entries are saved automatically. Print / Save PDF uses your device dialog. The separate one-page Letter PDF is a static blank comparison sheet, not fillable. These formats do not imply compatibility with paid products.</p><p>Next, use the <a href="/journal/business-plan-guide/">business-plan guide</a>, relevant <a href="/journal/business-plan-examples/">worked examples</a> and the <a href="/tools/one-page-business-plan-builder/">one-page plan builder</a> to turn an assumption into a dated test.</p>''')]
for slug,title,desc,guide in configs:
 s=t
 # Retain theme, navigation, privacy controls and dialogs; replace tool-specific body.
 s=s.replace('business-startup-checklist',slug).replace('data-day2','data-day3').replace('d2-','d3-').replace('day2-planning-tools','day3-planning-tools').replace('20261105','20261106').replace('November 5, 2026','November 6, 2026')
 oldtitle='Free Business Startup Checklist: Evidence, Owners &amp; PDF';s=s.replace(oldtitle,html.escape(title));s=s.replace('Free Business Startup Checklist: Evidence, Owners & PDF',title)
 import re
 s=re.sub(r'<meta name="description" content="[^"]*">',f'<meta name="description" content="{html.escape(desc)}">',s)
 s=s.replace('Turn preparation into assigned actions with evidence. Statuses are your manual records; this checklist does not verify permits, legal compliance or launch readiness.', 'Plan your day with exact time blocks and identify duplicate time promises.' if slug=='daily-schedule-builder' else 'Compare your own evidence and constraints before choosing a small business test.')
 s=s.replace('Download blank + example checklist PDF','Download blank worksheet PDF').replace('Download checklist CSV','Download reviewed CSV')
 begin=s.index('<div id="d3-rows">');end=s.index('<button type="submit">',begin)
 extra='<div class="d1-grid"><label>Day start<input id="d3-start" type="time" required></label><label>Day end<input id="d3-end" type="time" required></label></div>' if slug=='daily-schedule-builder' else '<fieldset><legend>Criterion weights (0–10)</legend><div class="d1-grid">'+''.join(f'<label>{name}<input id="d3-weight{i}" type="number" min="0" max="10" step="1" value="1" required></label>' for i,name in enumerate(['Customer evidence','Delivery fit','Cash fit','Testability']))+'</div></fieldset>'
 s=s[:begin]+extra+'<div id="d3-rows"></div><button id="d3-add" type="button">Add '+('entry' if slug=='daily-schedule-builder' else 'idea')+'</button>'+s[end:]
 begin=s.index('<h2>Use a startup checklist');end=s.index('</section></main>',begin);s=s[:begin]+guide+s[end:]
 s=s.replace('/assets/css/day3-planning-tools.css?v=20261106','/assets/css/day3-planning-tools.css?v=20261106')
 p=R/'tools'/slug/'index.html';p.parent.mkdir(exist_ok=True);p.write_text(s)
 # One-page static original writing sheet.
 c=canvas.Canvas(str(R/'downloads'/f'{slug}.pdf'),pagesize=letter);c.setTitle(title);c.setAuthor('NexalyPlanner');c.setFillColor(HexColor('#176c66'));c.rect(0,744,612,48,fill=1,stroke=0);c.setFillColor(HexColor('#ffffff'));c.setFont('Helvetica-Bold',14);c.drawString(40,763,'NEXALYPLANNER / FREE WORKSHEET');c.setFillColor(HexColor('#203d4a'));c.setFont('Helvetica-Bold',21);c.drawString(40,706,'Daily schedule' if slug=='daily-schedule-builder' else 'Business idea comparison');c.setFont('Helvetica',10);c.drawString(40,680,'Name: __________________________   Fixed date: __________________');c.drawString(40,653,'Day window: __________ to __________' if slug=='daily-schedule-builder' else 'Weights: customer ____ delivery ____ cash ____ testability ____')
 if slug=='daily-schedule-builder':
  c.drawString(40,620,'Task                                             Start              End              Notes')
  for i in range(10):c.line(40,602-i*35,572,602-i*35)
  notes=['Window minutes: ____   Task minutes: ____   Occupied minutes: ____','Free minutes: ____   Duplicate task minutes: ____','Free = window minus union of intervals. Overlap = task sum minus union.','Use same-day positive intervals; touching endpoints do not overlap.','Include breaks, travel and preparation. Revise conflicts before committing.']
 else:
  for i in range(3):
   y=610-i*125;c.setFont('Helvetica-Bold',11);c.drawString(40,y,f'Idea {i+1}: ____________________________________________________');c.setFont('Helvetica',10);c.drawString(40,y-24,'Ratings (0-5): customer ____ delivery ____ cash ____ testability ____');c.drawString(40,y-48,'Evidence / uncertainty: __________________________________________');c.line(40,y-77,572,y-77)
  notes=['Score = sum(rating x weight) / (5 x sum of weights) x 100.','Use integer weights 0-10; at least one positive. Higher ratings mean better fit.','Equal weighted points share rank. Ratings are subjective assumptions.','Scores do not predict demand, profit, funding or business viability.','Next test / owner / cost ceiling / date: ______________________________']
 for i,line in enumerate(notes):c.drawString(40,225-i*23,line)
 c.setFont('Helvetica',8);c.drawString(40,35,'nexalyplanner.com | US Letter | Static writing sheet, not fillable | 1 / 1');c.save()
(R/'assets/css/day3-planning-tools.css').write_text((R/'assets/css/day2-planning-tools.css').read_text().replace('d2-','d3-')+'\n.d3-row{min-width:0}.d3-row input,.d3-row textarea{width:100%;box-sizing:border-box}.d3-row{margin:1rem 0;padding:1rem;border:1px solid #b8cbc5;border-radius:12px}\n')
print('Two tools and two original PDFs created')
